"""Second clinical arithmetic checkpoint: renal arithmetic, liquid quantity, and one self-audit correction."""
import copy
import json
from build_b01 import ROOT, DAY, variable as v, source, reference as ref, rejection as reject, record, BC_LICENSE, BC_REDIST, BCVER

UNKNOWN_RIGHTS = "No reusable-content license or terms granting redistribution were established for this accessed version; terms unknown. Public availability alone is not legal clearance."
SHORT_REDIST = "Includes only original short evidence paraphrases, equations and attributed numerical facts, not a full source document or images. Further redistribution/use rights remain unverified; no endorsement claimed."
