        [source("nordx-clearance", "NorDx Laboratories: CRCLR, Creatinine Clearance, Serum and Urine", "https://nordx.testcatalog.org/show/CRCLR", "Live catalog inspected 2026-11-03; includes effective 2025-06-24 eGFR panel note, not a dated clearance-equation revision", "Clinical Significance: calculation and example; Important Note; Specimen Collection and Handling", "Gives the timed-volume clearance identity and reports 168.3 mL/min for a complete 2424 mL, 1440 min collection with 200.0 and 2.00 mg/dL concentrations.", "Catalog footer: portions copyright 2026 Mayo Foundation. Linked terms resolve to https://www.mayocliniclabs.com/customer-service/policies, Terms of Use, Intellectual Property Rights (reviewed May 1, 2024), inspected 2026-11-03; restrict source-material copying beyond personal noncommercial use without consent. Applicability to independently authored mathematical facts is not resolved here.", SHORT_REDIST),
         source("nkf-distinction", "NKF: Cockcroft-Gault equation limitations", NKF_LIMITS, "Live HTML inspected 2026-11-03", "Limitations of the Cockcroft-Gault equation, third bullet", "Distinguishes measured creatinine clearance from measured GFR.", UNKNOWN_RIGHTS, SHORT_REDIST)],
        [ref("published-nordx-collection", {"U":2,"V":0.002424,"P":0.02,"t":86400}, 2.805e-6, 8.33333333334e-10,
             "Published result 168.3 mL/min converted to m^3/s, not replaced with the recomputed 168.333... . Inputs 200.0 and 2.00 mg/dL become 2 and 0.02 kg/m^3; 2424 mL becomes 0.002424 m^3 and 1440 min becomes 86400 s. Half the reported tenth mL/min, converted to m^3/s, explains tolerance.", "NorDx CRCLR Clinical Significance example; published pedagogical calculation, not patient accuracy evidence."),
         ref("independent-excreted-mass-route", {"U":1.2,"V":0.0012,"P":0.01,"t":86400}, 1.6666666666666667e-6, 1e-17,
             "Independent mass-balance arithmetic: 120 mg/dL in 12 dL urine contains 1440 mg; at 1 mg/dL serum this corresponds to 1440 dL of serum per day, hence 100 mL/min. Normalize to m^3/s. This checks units/conservation independently of evaluating the stored expression, not clinical measurement accuracy.", "Curator-constructed 24-hour specimen example, with arithmetic-only tolerance.")],
        [reject({"U":2,"V":0.002424,"P":0,"t":86400}, "Zero serum concentration makes clearance undefined."),
         reject({"U":2,"V":0,"P":0.02,"t":86400}, "No positive collected specimen volume exists for the supplied urine assay."),
         reject({"U":2,"V":0.002424,"P":0.02}, "Collection duration is required; nominal day must not be silently substituted.", "missing-input")],
        "Forward only in this assignment. Clearance inversions are explicitly deferred rather than presented as new records or executable solve directions. No inverse-target examples are asserted under that assignment exception. Original guards and matched complete-collection context remain required. P=0 or t=0 is undefined; a zero U limit with positive P,V,t gives zero forward clearance without supplying an inverse view.",
