        [v("D", "D (Desired Amount)", "input", "prescribed_drug_mass_per_administration", "Active-drug mass already specified for this single administration on the same labeled active-moiety basis as H.", "kg", "M", ctx, "Finite nonnegative; zero is the no-amount arithmetic boundary, not a prescribed therapy."),
         v("H", "H (Dose on hand)", "input", "labeled_active_drug_reference_mass", "Mass of the specified active drug contained in stock reference volume Q; not total formulation mass.", "kg", "M", ctx, "Finite strictly positive labeled reference mass; same moiety/salt-equivalent convention as D."),
         v("Q", "Introduced Q maps to stock Volume in D/H x Volume", "input", "labeled_liquid_reference_volume", "Final liquid formulation volume containing labeled active-drug mass H.", "m^3", "L^3", ctx, "Finite strictly positive; final homogeneous formulation, not diluent volume before reconstitution."),
         v("V", "Introduced V maps to liquid Dose/Quantity for dose", "output", "prescribed_liquid_medication_volume", "Unrounded liquid volume containing D under the specified stock mass-to-volume proportion.", "m^3", "L^3", ctx, "Finite nonnegative proportional volume. Device resolution, available stock count and administration decisions are not outputs.")],
        ["D >= 0", "H > 0", "Q > 0"],
